window.INURA_PROGRAM_ARCHIVE = {"program": {"1": [], "2": [], "3": [{"id": 1077, "title": "June5_Production Ecosystem Under Pressure: Craft Neighborhoods and Urban Transformation in Beyoğlu", "time": "08:30-15:00", "provider": "Aslı Kıyak İngin", "capacity": "10", "registered": 10}, {"id": 1065, "title": "June5_A day in a commerce, production and a co-production quarter:  İMÇ and its modern posture", "time": "09:30-15:00", "provider": "Ayşe Erek", "capacity": "12", "registered": 8}, {"id": 1062, "title": "June5_From Prison to Housing, Kiptas Bayrampasa", "time": "09:30-15:00", "provider": "Onur Ceritoğlu", "capacity": "12", "registered": 12}, {"id": 1091, "title": "June5_Sarıyer–Derbent: Negotiating Urban Transformation at Istanbul’s Metropolitan Frontier", "time": "09:45-15:00", "provider": "Ayşe Gümec Karamuk, Ebru Kurt Özman", "capacity": "12", "registered": 12}], "4": [{"id": 1073, "title": "June6_Three Layers of Transformation in Kadıköy: Big Infrastructure Investments, Cultural Flagship Projects, and Neighborhood Gentrification", "time": "09.15-15:00", "provider": "Araf Öykü Türken, Aysim Türkmen, Tolga İslam", "capacity": "12", "registered": 12}, {"id": 1082, "title": "June6_Urban Food Communities as a Form of Solidarity, Struggle, Commons and Care", "time": "09:00-15:30", "provider": "Aslı Kıyak İngin", "capacity": "10", "registered": 6}, {"id": 1133, "title": "June6_Fikirtepe, the second most dense residential area on the planet. Neoliberal win-win model hitting the wall", "time": "09:15-15:00", "provider": "Orhan Esen", "capacity": "9", "registered": 9}, {"id": 1097, "title": "June6_The Invisible Side of Gentrification in Istanbul’s Trendy Asian-Side Neighborhoods", "time": "09:15-15:00", "provider": "Ezgi Karaoğlu", "capacity": "10", "registered": 10}, {"id": 1070, "title": "June6_Kadıköy Urban Transformation & Earthquake Resilience Tour", "time": "09:15-15:00", "provider": "Murat Güney", "capacity": "10", "registered": 5}], "5": [{"id": 1056, "title": "June7_The Westend: Waves and Layers of Urbanity", "time": "09:15-18:00", "provider": "Emrah Altınok, Onur Ceritoğlu, Orhan Esen", "capacity": "28", "registered": 27}, {"id": 1052, "title": "June7_Eastern Suburbia: From Financial Spectacle to Migrant Peripheries", "time": "09:15-18:00", "provider": "Aysim Türkmen, Sinan Logie, Tolga İslam", "capacity": "22", "registered": 15}], "6": []}, "details": {"1052": {"title": "June7_Eastern Suburbia: From Financial Spectacle to Migrant Peripheries", "description": "<strong>Eastern Suburbia: From Financial Spectacle to Migrant Peripheries</strong>\r\n<p style=\"font-weight: 400;\">Sinan Logie, Aysim Türkmen, Tolga İslam</p>\r\n<p style=\"font-weight: 400;\">Our tour charts the dramatic socio-spatial restructuring of Istanbul’s eastern periphery, exploring how global capital, state-led housing schemes, and international migration reshape the city’s outer edges. The journey begins in Ataşehir with a stark spatial and ideological juxtaposition: the towering spectacles of the Istanbul Financial Center standing directly opposite the Ataşehir Mimar Sinan Mosque—a state-backed, anachronistic replica of the 16th-century Selimiye Mosque in Edirne. The route then moves through the rapid suburbanization, gated communities, and mass consumption nodes of Çekmeköy and Viaport. This trajectory reveals how speculative real estate and corporate infrastructure have pushed the boundaries of the metropolis outward, converting former rural or soft landscapes into highly commodified urban zones.</p>\r\n<p style=\"font-weight: 400;\">The second half of the tour shifts focus toward the complex social fabric of the periphery, centering on Sultanbeyli—a district historically defined by informal housing (<em>gecekondu</em>) and internal migration, now positioned as a critical hub for international migration. Through a comprehensive briefing at the Association for Refugees (<em>Mülteciler Derneği</em>), we will examine the spatial distribution of Syrian migration within Istanbul, municipal and NGO governance models, and the everyday social encounters and tensions between host and migrant communities. The excursion concludes at YUNT, a contemporary cultural venue in Sultanbeyli, prompting a final discussion on how private cultural infrastructure and artistic institutions negotiate their presence within working-class peripheral neighborhoods.</p>\r\n\r\n<h3><strong>FIELD EXCURSION PROGRAM: ISTANBUL’S EASTERN PERIPHERY</strong></h3>\r\n<p style=\"font-weight: 400;\"><strong>Date:</strong> June 7, Sunday (Draft Schedule)</p>\r\n\r\n<ul>\r\n \t<li><strong>09:15</strong> – Departure from Elmadağ (Meeting Point)</li>\r\n \t<li><strong>10:30 – 10:45</strong> – <strong>Ataşehir Mimar Sinan Mosque &amp; Istanbul Financial Center</strong>\r\n<ul>\r\n \t<li><em>Theme: Confronting global finance capital and neo-historical architecture on the city's edge.</em></li>\r\n</ul>\r\n</li>\r\n \t<li><strong>11:15 – 11:30</strong> – <strong>Çekmeköy</strong>\r\n<ul>\r\n \t<li><em>Theme: Rapid suburbanization, gated communities, and mid-class housing expansion.</em></li>\r\n</ul>\r\n</li>\r\n \t<li><strong>11:45 – 12:00</strong> – <strong>Viaport Complex</strong>\r\n<ul>\r\n \t<li><em>Theme: Mega-retail infrastructure anchoring peripheral growth.</em></li>\r\n</ul>\r\n</li>\r\n \t<li><strong>12:30 – 13:30</strong> – <strong>Lunch Break at Gölet (Sultanbeyli)</strong></li>\r\n \t<li><strong>13:45 – 15:30</strong> – <strong>Visit to the Association for Refugees (<em>Mülteciler Derneği</em>)</strong>\r\n<ul>\r\n \t<li><em>Theme: Tracing the district’s journey from informal housing (gecekondu) to a key hub of international migration. Briefing on governance models, NGO operations, and social cohesion.</em></li>\r\n</ul>\r\n</li>\r\n \t<li><strong>15:45 – 16:15</strong> – <strong>YUNT Contemporary Cultural Center</strong>\r\n<ul>\r\n \t<li><em>Theme: The role of private cultural infrastructure and art institutions within an evolving peripheral neighborhood.</em></li>\r\n</ul>\r\n</li>\r\n \t<li><strong>16:15</strong> – Return Journey</li>\r\n</ul>\r\n<p style=\"font-weight: 400;\"><img class=\"alignnone size-full wp-image-1053\" src=\"/assets/tolga_bus_tour.jpg\" alt=\"\" width=\"939\" height=\"533\" /></p>\r\n<p style=\"font-weight: 400;\"><a href=\"https://www.google.com/maps/d/edit?mid=1A4diyPBq4XOQl-0KXE4DqwbeMz833ZQ&amp;usp=sharing\">https://www.google.com/maps/d/edit?mid=1A4diyPBq4XOQl-0KXE4DqwbeMz833ZQ&amp;usp=sharing</a></p>\r\n<p style=\"font-weight: 400;\"><strong> </strong></p>", "time": "09:15-18:00", "provider": "Aysim Türkmen, Sinan Logie, Tolga İslam", "provider_link": "/providers.html#provider-941", "capacity": "22", "registered": 15, "is_full": false, "has_whatsapp": true}, "1056": {"title": "June7_The Westend: Waves and Layers of Urbanity", "description": "<div>\r\n<p class=\"Body\">In Istanbul, the closer you come to the western edge of the metropolitan area, the more Asian-like it gets. This is where size matters—and density, too. This excursion is meant to help participants comprehend the mechanisms of where, when, and how the 16 million Istanbulites were packed together.</p>\r\n\r\n</div>\r\n<div>\r\n<p class=\"Default\"><span lang=\"EN-US\">The tour follows the waves of industrialization, deindustrialization, and reindustrialization: Istanbul expelled industrial production from its historical core while simultaneously relocating it to its own active fringes. We will read this process through the dynamically transforming patterns of housing areas. We will follow successive parallel valleys extending westbound into the agricultural zone in Thrace, as well as successive layers of urbanization extending northbound following highway constructions into the fragile metropolitan ecozone toward the Black Sea. This grid of valleys and layers functions as a basic textbook of housing patterns and actors. Institutions of formal mass housing development, as well as phases of informal and post-informal housing production, will appear in a chronological and systemic narrative.</span></p>\r\n\r\n</div>\r\n<div>\r\n<p class=\"Default\"><b><span lang=\"EN-US\">1. Former Working Class Residential Areas at the Industrial Zone Topkapı in Transition: Cuba, Tozkoparan</span></b><span lang=\"EN-US\">\r\n</span><span lang=\"EN-US\">Just outside the city walls an industrial zone emerged from the 1950s onward and triggered working-class settlements in its vicinity. Since the 1990s, this centrally located area has been undergoing a post-industrial transformation. One of the last relics of the original <i>gecekondu</i> belt is still visible close to the first highway ring. The inhabitants, in resistance to forced state-and-market-driven transformation, self-assigned the name <b>Küba</b> to their settlement. The adjacent <b>Tozkoparan</b> is one of the rare (about 50 compounds in all of Istanbul) <i>Gecekondu</i> <i>Prevention Areas</i>—i.e. formal working-class residential projects realized directly by the Ministry of Public Works in the 1960s. This modernist settlement with approximately 3,000 units has been demolished very recently; the last units are disappearing right now. The recent transformation under a PPP model is driven by the Güng</span><span lang=\"SV\">ö</span><span lang=\"EN-US\">ren district municipality, enabled by the new-TOKI regime (see below, 5).</span></p>\r\n\r\n</div>\r\n<div>\r\n<p class=\"Default\"><b><span lang=\"EN-US\">2. Atak</span></b><b><span lang=\"SV\">ö</span></b><b><span lang=\"EN-US\">y, the Middle Class New Town</span></b><span lang=\"EN-US\">\r\n</span><span lang=\"EN-US\">The first modern mass housing project after WWII was realized by the state-owned <i>Emlak </i>(Real Estate) Bank and comprises 11 sectors with 80,000 inhabitants. The institution was originally founded in the 1930s to solve the housing problem of Ankara, the fast-growing new national capital. Atak</span><span lang=\"SV\">ö</span><span lang=\"EN-US\">y, one of their three initial Istanbul projects, was placed along the Marmara coastal express road and served the housing needs of the motorized middle and upper-middle classes, who desired to escape the inner districts with their narrow roads. We will stop at <b>Sector I</b>, with its praised settlement pattern and modernist architectural solutions, and drive through later (2-11) sectors of Atak</span><span lang=\"SV\">ö</span><span lang=\"EN-US\">y; 21st-century additions are developed no longer as sectors but as enclosed </span><span dir=\"RTL\" lang=\"AR-SA\">“</span><span lang=\"EN-US\">PPP-projects,” mainly on the waterfront.</span></p>\r\n\r\n</div>\r\n<div>\r\n<p class=\"Default\"><b><span lang=\"EN-US\">3. Halkalı Sub-town / Working Class</span></b><span lang=\"EN-US\">\r\n</span><span lang=\"EN-US\">In the mid-1980s, the production of formal mass housing for the working class inevitably came onto the agenda. TOKI, the Mass Housing Administration, was founded and began playing a pivotal role in resculpting Istanbul into its new macroform alongside the new east–west highway network, with formally separated zones for living and production. We will stop at <b><i>Sector I</i></b> of Halkalı (total 200,000 inhabitants in all sectors), with its elaborate architectural solutions, and take a break at <b><i>Arena Mall,</i></b> an open-air structure at the interface of formal and informal development areas. Commercial infrastructures are often used to create public space. We drive through later sectors, with dystopian character devoid of any urbanity, to finally arrive in the recently built section with branded living compounds. In <b><i>The Bosphorus City</i></b> and </span><b><i><span lang=\"NL\">Palaces of Istanbul</span></i></b><span lang=\"EN-US\">, the developer sincerely meant to copy-paste the metropolis itself. The result: a must-see. In the adjacent <i>Lounge Istanbul</i>, an honest architect tried to escape the dictated persiflage. <i>Tema Istanbul</i>, the originally most ambitious project of this episode simply derailed and became a mediocre giant.</span></p>\r\n\r\n</div>\r\n<div>\r\n<p class=\"Default\"><b><span lang=\"EN-US\">4. The Second Wave of Informality</span></b><span lang=\"EN-US\">\r\n</span><span lang=\"EN-US\">Altınşehir and Şahintepe are two vast areas of “late informality under market conditions” (not: <i>gecekondu</i>). They are tightly enclosed by formally developed zones surrounding the second highway ring. The course of Kanal Istanbul—that phantom mega-project—will allegedly run between the two; the <i>Olympic Stadium</i> is just next door.</span><span lang=\"EN-US\">\r\n</span><i><span lang=\"EN-US\">Altınşehir</span></i><span lang=\"EN-US\"> is currently being formalized with a small-capital transformation model; <i>Ş</i></span><i><span lang=\"DE\">ahintepe</span></i><span lang=\"EN-US\">, however, is on a different course: that of resistance. Our stopovers in this section will include: (a) an <b>informal </b></span><b><span dir=\"RTL\" lang=\"AR-SA\">“</span></b><b><span lang=\"ES-TRAD\">campus</span></b><b><span lang=\"EN-US\">”</span></b><span lang=\"EN-US\"> for recycling construction material, (b) the <b>neighborhood association</b> in Şahintepe, and (c) a <b>viewpoint</b> upon the Sazlıdere Valley, which should become the course of <b>Kanal Istanbul</b>.</span></p>\r\n\r\n</div>\r\n<div>\r\n<p class=\"Default\"><b><span lang=\"EN-US\">5. The Emergence of the Current Regime for Mainstream Mass Housing, by way of </span></b><b><span lang=\"DE\">Emlak/TOKI Fusion</span></b><span lang=\"EN-US\">\r\n</span><span lang=\"EN-US\">In the 1990s, Emlak Bank was assigned the new-generation housing project Bahçeşehir (</span><span dir=\"RTL\" lang=\"AR-SA\">“</span><span lang=\"EN-US\">The Garden City”) at the second highway, while work in Atak</span><span lang=\"SV\">ö</span><span lang=\"EN-US\">y continued. That decade of Emlak became one of utmost corruption, involving politicians, administration, and private actors; the bank had to be dissolved, and its assets, projects, and corporate culture were transferred to TOKI. During the 21st century, a distinctive regime of capital accumulation under state capitalism was established using this new Mass Housing Administration. We will allow ourselves only <b>short photo stops </b>while passing through ever-expanding <i>Ispartakule </i>and<i> Bahçeşehir</i> newtowns.</span></p>\r\n\r\n</div>\r\n<div>\r\n<p class=\"Default\"><b><span lang=\"EN-US\">6. Citizens Correct Academic Planning</span></b><span lang=\"EN-US\">\r\n</span><span lang=\"EN-US\">Boğazk</span><span lang=\"SV\">ö</span><span lang=\"EN-US\">y is a neighborhood of working-class cooperatives, between white collar Bahçeşehir to its south and the Hadımk</span><span lang=\"SV\">ö</span><span lang=\"EN-US\">y industrial area in the north. Morphologically, it is a textbook example of </span><i><span lang=\"DE\">Blockrandbebauung</span></i><span lang=\"EN-US\"> (perimeter block development) with green inner courtyards. However, almost two decades after the completion of construction works, it was still a ghost town. The owners took affairs into their own hands and corrected the grand planning fault: Boğazk</span><span lang=\"SV\">ö</span><span lang=\"EN-US\">y became a very livable area. A <b>stroll </b>down the main street.</span></p>\r\n\r\n</div>\r\n<div>\r\n<p class=\"Default\"><b><span lang=\"EN-US\">7. Esenyurt, the Powerhouse of Istanbul</span></b><span lang=\"EN-US\">\r\n</span><span lang=\"EN-US\">On the way back, we will allow ourselves a last stopover at the main square of Esenyurt, the largest of Istanbul</span><span dir=\"RTL\" lang=\"AR-SA\">’</span><span lang=\"EN-US\">s 39 districts, with over one million inhabitants. Esenyurt, where urbanization began in the mid-1980s, is today the powerhouse of Istanbul, bearing the major load of industrial production, its harbor, and its power plant. The political history of this highly contested district reads like a crime novel, while the cityscape reflects waves of unchained developmentalism from a society entirely of migratory background.</span></p>\r\n<img class=\"aligncenter size-full wp-image-1105\" src=\"/assets/b1.jpg\" alt=\"\" width=\"1002\" height=\"564\" />\r\n\r\n</div>\r\n<div>\r\n\r\n“Cuba, our homeland” Graffiti, Küba mahallesi. source <a href=\"https://www.yenicaggazetesi.com/gazeteci-ismail-saymaz-kuba-mahallesinin-son-halini-paylasti-562576h.htm\">https://www.yenicaggazetesi.com/gazeteci-ismail-saymaz-kuba-mahallesinin-son-halini-paylasti-562576h.htm</a>\r\n\r\n<img class=\"aligncenter size-full wp-image-1106\" src=\"/assets/b2.jpg\" alt=\"\" width=\"1004\" height=\"495\" />\r\n\r\nBahçeşehir, “The Garden City”, contested illegal foodcourt development ontop the settlements’ lakeside park\r\n\r\n<img class=\"aligncenter size-full wp-image-1108\" src=\"/assets/b3.jpg\" alt=\"\" width=\"1004\" height=\"754\" />\r\n\r\nIstanbul, as copy pasted into its own Westend. Photo Orhan Esen\r\n\r\n<img class=\"aligncenter size-full wp-image-1110\" src=\"/assets/b5.jpg\" alt=\"\" width=\"1004\" height=\"564\" />\r\n\r\nBoğazköy, Citizen based post-planning. Photo Orhan Esen\r\n\r\n<img class=\"aligncenter size-medium wp-image-1109\" src=\"/assets/b4-224x300.png\" alt=\"\" width=\"224\" height=\"300\" />\r\n<p style=\"text-align: center;\">@Şahintepe People’s Solidarity Association. Photo Orhan Esen</p>\r\n<img class=\"aligncenter size-full wp-image-1111\" src=\"/assets/b7.jpg\" alt=\"\" width=\"768\" height=\"579\" />\r\n\r\nSouthern end of the Sazlıdere (or “Reed creek”) valley, water protection area being demolished. Course of the Phantom Kanal Istanbul.<span class=\"Apple-converted-space\">  </span>Photo Orhan Esen\r\n\r\n<img class=\"aligncenter size-full wp-image-1112\" src=\"/assets/b6.jpg\" alt=\"\" width=\"918\" height=\"581\" />\r\n\r\nIspartakule “Towers of Sparta” development area, between the Garden City (left)and informal Şahintepe “Falcons’ Hill” (right), between lake Küçükçekmece and Northern Forestbelt\r\n\r\nsource: https://www.insaatyatirim.com/Haber/49799/ihlas-gayrimenkul-un-ispartakule-deki-yeni-projesi-bizim-evler-12-satisa-cikti\r\n\r\n<img class=\"size-medium wp-image-1113 aligncenter\" src=\"/assets/b8-224x300.png\" alt=\"\" width=\"224\" height=\"300\" />\r\n<p style=\"text-align: center;\"><span class=\"Apple-converted-space\"> </span>@ Campus for circular construction economy, Altınşehir “Goldentown”, Photo Onur Ceritoğlu</p>\r\n<p class=\"Default\"><span lang=\"EN-US\"><img class=\"alignnone size-full wp-image-1057\" src=\"/assets/PHOTO-2026-05-25-14-49-57.jpg\" alt=\"\" width=\"1600\" height=\"758\" /></span></p>\r\n\r\n</div>\r\n<div></div>\r\n<div>\r\n\r\nhttps://www.google.com/maps/d/u/0/viewer?ll=41.02960552113402%2C28.770943665347012&amp;z=12&amp;mid=1Ai45AayL-QN0ly7eRA3GDSRCP_8qfjA\r\n\r\n</div>\r\n<div>\r\n<p class=\"Default\"><span lang=\"EN-US\"> </span></p>\r\n\r\n</div>\r\n<div>\r\n<p class=\"Default\"><span lang=\"EN-US\"> </span></p>\r\n\r\n</div>\r\n<div>\r\n<p class=\"Default\"><span lang=\"EN-US\"> </span></p>\r\n\r\n</div>\r\n<div>\r\n<p class=\"Default\"><span lang=\"EN-US\"> </span></p>\r\n\r\n</div>\r\n<div>\r\n<p class=\"Default\"><span lang=\"EN-US\"> </span></p>\r\n\r\n</div>\r\n<div>\r\n<p class=\"Default\"><span lang=\"EN-US\"> </span></p>\r\n\r\n</div>\r\n<div>\r\n<p class=\"Default\"><span lang=\"EN-US\"> </span></p>\r\n\r\n</div>\r\n<div>\r\n<p class=\"Default\"><span lang=\"EN-US\"> </span></p>\r\n\r\n</div>\r\n<div>\r\n<p class=\"Default\"><span lang=\"EN-US\"> </span></p>\r\n\r\n</div>\r\n<div>\r\n<p class=\"Default\"><span lang=\"EN-US\"> </span></p>\r\n\r\n</div>\r\n<div>\r\n<p class=\"Default\"><span lang=\"EN-US\"> </span></p>\r\n\r\n</div>\r\n<div>\r\n<p class=\"Default\"><span lang=\"EN-US\"> </span></p>\r\n\r\n</div>\r\n<div>\r\n<p class=\"Default\"><span lang=\"EN-US\"> </span></p>\r\n\r\n</div>\r\n<div>\r\n<p class=\"Default\"><span lang=\"EN-US\"> </span></p>\r\n\r\n</div>\r\n<div>\r\n<p class=\"Default\"><span lang=\"EN-US\"> </span></p>\r\n\r\n</div>", "time": "09:15-18:00", "provider": "Emrah Altınok, Onur Ceritoğlu, Orhan Esen", "provider_link": "/providers.html#provider-946", "capacity": "28", "registered": 27, "is_full": false, "has_whatsapp": true}, "1062": {"title": "June5_From Prison to Housing, Kiptas Bayrampasa", "description": "KİPTAŞ in the Bayrampaşa district is a housing project developed by KİPTAŞ, the city-owned company that transitioned from the AKP-led municipality to the CHP-led municipality. The project’s completion is a unique example of continuity through the change in municipal administration in 2019, when Ekrem İmamoğlu became mayor of Istanbul. Although the opposition party (CHP) had previously criticized the project, the new administration had to complete it after taking office.\r\n\r\nPart of the project site was formerly occupied by the Sağmalcılar state prison with a controversial history. Urban transformation in the area began after it was declared a Reserve Area in 2013. Using a build–transfer–vacate model, the project enabled residents to move directly into newly completed homes through temporary contracts. Relocation and title transfer processes, however, are still ongoing as part of the project’s first phase.\r\n\r\nDue to financial difficulties, disagreements, bureaucratic obstacles, and political conflict, the demolition of the remaining buildings has not been completed, leaving a landscape of debris on the adjacent site as part of the project’s second phase. In this sense, the urban transformation process remains frozen.\r\n\r\n<img class=\"alignnone size-full wp-image-1063\" src=\"/assets/Ekran-Resmi-2026-05-26-21.33.00.jpg\" alt=\"\" width=\"1394\" height=\"784\" />\r\n\r\n<img class=\"alignnone size-full wp-image-1064\" src=\"/assets/Ekran-Resmi-2026-05-26-21.33.12.jpg\" alt=\"\" width=\"1377\" height=\"982\" />\r\n\r\n<b>Technical information</b>\r\n\r\nWe will start 09:30 at Konak Hotel. We will use the metro from Taksim, with one interchange in Yenikapı. Total ride time is ca 35 minutes. To get to the project site we will have an easy walk of ca 10 minutes. The terrain is relatively flat, asphalt and cobbles. we will spend 2-3 hours outdoors at the site (short distances to walk) as well as in the “Urban Transformation center”and in the local Library, so time allows. In physical terms, this is a “very easy” tour.\r\n\r\nWe will eat at a börek shop located in the project area. If need be, there are also alternatives in the neighbourhood.\r\n\r\nThe field trip will be conducted by Onur Ceritoğlu.\r\n\r\nonurceritoglu@gmail.com\r\n\r\n+41 77 486 53 27 active on whatsapp and Signal", "time": "09:30-15:00", "provider": "Onur Ceritoğlu", "provider_link": "/providers.html#provider-945", "capacity": "12", "registered": 12, "is_full": true, "has_whatsapp": true}, "1065": {"title": "June5_A day in a commerce, production and a co-production quarter:  İMÇ and its modern posture", "description": "<p data-start=\"0\" data-end=\"682\">Half-day excursion at IMÇ, a symbol of modern ideas in design and art, and an urban planning approach of the 1960s, (Tekeli/Sisa Architects) relating to the environmental and historical context in which it is located. The complex comprising of 6 blocks along a major urban axis is designed as a public space, easily accessible from the street, and hosts works by prominent artists in the facades and internal courtyards, attempting to bring art and life into this commercial quarter. Originally initiated by textile wholesalers, the IMÇ hosted in 1970s/90s also the music industry, serving not only as a place for consumption and commerce but also as a production hub for musicians.</p>\r\n<p data-start=\"684\" data-end=\"885\">Recently, several self-initiated spaces for art and some art and architecture oﬃces have increased in number, expanding the historically productive character of the site into new forms of intervention.</p>\r\n<p data-start=\"887\" data-end=\"1284\" data-is-last-node=\"\" data-is-only-node=\"\">Participants will gain insight into the 1960s ideology in art, architecture, and urban planning, as well as the failures and conflicts the space has experienced, its role since the 2000s amid rapid commercialization and urban renewal, the activist stances and claims to protect it, and the collective eﬀorts to sustain it as a productive cluster for artistic initiatives and cultural institutions.</p>\r\n<b>Questions:</b>\r\nWhat is the legacy of this space? How is it positioned within discussions of urban heritage?\r\n\r\nWhat does it represent in terms of architectural and urban planning discourse?\r\n\r\nWhat kind of space for production does it represent today?\r\n\r\nHow do the inhabitants interact with the space and with their neighbours?\r\n\r\nThis is the ground. We’ll visit and discuss together.\r\n<p data-start=\"887\" data-end=\"1284\" data-is-last-node=\"\" data-is-only-node=\"\"><a href=\"http://www.mimarlikdergisi.com/index.cfm?sayfa=mimarlik&amp;DergiSayi=410&amp;RecID=4225\"><img class=\"wp-image-1066 aligncenter\" src=\"/assets/Ekran-Resmi-2026-05-26-21.36.18.jpg\" alt=\"\" width=\"576\" height=\"399\" /></a></p>\r\n<p style=\"text-align: center;\"><a href=\"http://www.mimarlikdergisi.com/index.cfm?sayfa=mimarlik&amp;DergiSayi=410&amp;RecID=4225\">View from the Western Façade, Birds, Kuzgun Acar (1928-1976), sculpture / relief, 1st Block </a></p>\r\n<a href=\"http://http://www.mimarlikdergisi.com/index.cfm?sayfa=mimarlik&amp;DergiSayi=410&amp;RecID=4225\"><img class=\"aligncenter size-medium wp-image-1067\" src=\"/assets/Ekran-Resmi-2026-05-26-21.36.42-279x300.png\" alt=\"\" width=\"279\" height=\"300\" /></a>\r\n\r\n<b>Information on the route</b>\r\n\r\n<i>We will take a short, 2 stations metro ride to the historical peninsula.</i><i></i>\r\n\r\nWithin a 10 minutes walk, passing by the same era Istanbul Metropolitan Municipality building (Erol, 1953) we will arrive at the compound comprising of 6 blocks within 800 meters, pleasantly placed onto a slope with roughly a hundred meters difference of altitude. Blocks usually comprise of 3 visible floors, organized around open atriums, pleasant public/communal spaces. We will be moving downhill block-hopping. at some blocks we will also climb ontop the terrace floors to experience the visual axes linking to the historical environment, the building is embedded within. Whenever we visit the studios, art spaces and institutions located at İMÇ, we will be indoors. Its physically an easy tour with short walking distances. Some physical effort will be needed for these lots of stairs, however we will mostly be moving downstairs.\r\n\r\nThe tour will depart at 09 30 from Konak hotel.\r\n\r\nLunch will be taken at a simple eatery (rice and stew type) at a tea kiosk, who serves daily the local community of artists and shopowners in the 5th block.\r\n\r\nAfter the visit of the IMÇ we have some time to explore the harbor area. We have the option to visit the exhibition<span class=\"Apple-converted-space\">  </span>Love, D-mark and death at Depo Istanbul.\r\n\r\nhttps://www.depoistanbul.net/en/love-d-mark-and-death/\r\n\r\nThe excursion will be conducted by <b>Ayşe Erek</b><i></i><i></i>\r\n<ul>\r\n \t<li><a href=\"mailto:aysenerek@gmail.com\">aysenerek@gmail.com</a></li>\r\n \t<li>whatsapp: +905325700896</li>\r\n \t<li>Ayşe uses signal as well</li>\r\n</ul>", "time": "09:30-15:00", "provider": "Ayşe Erek", "provider_link": "/providers.html#provider-951", "capacity": "12", "registered": 8, "is_full": false, "has_whatsapp": true}, "1070": {"title": "June6_Kadıköy Urban Transformation & Earthquake Resilience Tour", "description": "&nbsp;\r\n\r\n<b><i>Tour Guide:</i></b><b><i> Murat Güney<span class=\"Apple-converted-space\"> </span></i></b>\r\n\r\n<b><i>Date:</i></b><b><i> 6 June 2026</i></b>\r\n\r\nThis walking tour explores the intersection of gentrification, and earthquake-resilient architecture in one of Istanbul’s most iconic districts. The tour aims to discuss how the earthquake risk in Istanbul is instrumentalized for gentrification and production of wealth through urban transformation projects in Kadıköy. <img src=\"data:image/png;base64,\" alt=\"pastedGraphic.png\" />\r\n\r\n<b>Tour Schedule</b>\r\n<table cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr>\r\n<td valign=\"top\"><b>Time</b><b></b></td>\r\n<td valign=\"top\"><b>Activity</b><b></b></td>\r\n<td valign=\"top\"><b>Key Focus</b><b></b></td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\"><b>09:15</b><b></b></td>\r\n<td valign=\"top\"><b>Departure</b><b></b></td>\r\n<td valign=\"top\">Meet at Konak Hotel; transit via Metro &amp; Marmaray.</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\"><b>10:15</b><b></b></td>\r\n<td valign=\"top\"><b>Arrival</b><b></b></td>\r\n<td valign=\"top\">Arrival Terminal Kadıkoy</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\"><b>10:20 – 11:00</b><b></b></td>\r\n<td valign=\"top\"><b>Terminal Kadıköy</b><b></b></td>\r\n<td valign=\"top\">Short tour of the Asian side’s latest major gentrification site/shopping mall.</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\"><b>11:00 – 11:30</b><b></b></td>\r\n<td valign=\"top\"><b>Yoğurtçu Park &amp; Kurbağlıdere</b><b></b></td>\r\n<td valign=\"top\">Discovery of the renovated park and the rehabilitated creek.</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\"><b>11:30 – 12:00</b><b></b></td>\r\n<td valign=\"top\"><b>Break</b><b></b></td>\r\n<td valign=\"top\">Tea/Coffee stop at the Yoğurtçu Park teahouse.</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\"><b>12:00 – 12:45</b><b></b></td>\r\n<td valign=\"top\"><b>Moda Transformation</b><b></b></td>\r\n<td valign=\"top\">Site visit to newly constructed resilient buildings: A stop at a privately renovated apartment building to discuss the individual owner-developer narrative, followed by a visit to the Istanbul Municipality (KİPTAŞ) urban transformation site.</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\"><b>12:45 – 13:30</b><b></b></td>\r\n<td valign=\"top\"><b>Construction Hub</b><b></b></td>\r\n<td valign=\"top\">Walking through the high-density construction zones of Vehbi Sandal, Hasırcıbaşı, and Süleymanpaşa streets to see the scale of ongoing works. Observation of \"First-Row\" completed transformations versus ongoing \"Second-Row\" construction.<span class=\"Apple-converted-space\"> </span></td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\"><b>13:30 – 14:00</b><b></b></td>\r\n<td valign=\"top\"><b>Central Kadıköy, Bahariye &amp; Yeldeğirmeni</b><b></b></td>\r\n<td valign=\"top\">Transit through Bahariye St. to TAK Kadıköy. A discussion on why central Kadıköy sees less residential transformation compared to Moda; analyzing commercial value, and profit margins. <span class=\"Apple-converted-space\"> </span>\r\n\r\nObserving the Asian side’s oldest high-rise apartments in Yeldeğirmeni Neighborhood, originally built for the Haydarpaşa railway workers, highlighting the transition from worker-class housing to a modern trend-center.</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<b>Tour Logistics</b>\r\n<ul>\r\n \t<li><b>Duration:</b> Approx. 5 kms walking/talking within 180 minutes + 30 minutes rest.</li>\r\n \t<li><b>Difficulty:</b> <b>Middle</b>. The route is mostly flat with only a few minor inclines.</li>\r\n \t<li><b>Endpoints:</b> The tour concludes at <b>TAK Kadıköy</b> (Design Ateliers Kadıköy), where the Civic Forum will take place.<span class=\"Apple-converted-space\"> </span></li>\r\n \t<li>Warm lunch will be served in <b>TAK. </b>Snacks can be obtained at any point on the route.</li>\r\n</ul>\r\n<b>Tour Description:</b>\r\n\r\nThis tour aims to discuss how earthquake risk in Istanbul is instrumentalized for gentrification and wealth production through urban transformation projects in Kadıköy.\r\n\r\nThe risk of earthquakes is exploited by \"disaster capitalism\" to convert Istanbul into a massive construction site. Previous earthquakes in Turkey have been effectively used by the neoliberal market and the government as \"shock therapy\" to implement a construction-led development model. This approach favors the construction sector by introducing new incentives, exceptional rights, and interventions that might otherwise be challenged. The ongoing massive urban transformation and new mass housing projects are justified as improvements to the housing stock, intended to make residential buildings stronger and more resilient. However, one can observe that the motive of protecting lives is selective and operates according to the principles of a neoliberal market economy.\r\n\r\nWhile the city is ostensibly being made more resilient, the location of these interventions is determined selectively. Areas under actual earthquake risk mostly do not match the areas officially declared as disaster risks by the government. Instead, valuable land has been designated by the state and construction companies as disaster risk zones, targeting them for lucrative new urban transformation projects.\r\n\r\nAn efficient mechanism, based on the claim of protecting lives, works in Istanbul to produce wealth through construction. On the one hand, for those who already own an apartment on valuable land in an upper-middleclass neighbourhood of Istanbul, earthquake risk is a good excuse to demolish and rebuild their residences. Such transformation brings about a price increase of up to 100% during the reconstruction, which takes about two years. On the other hand, the housing stock in the areas actually under earthquake risk have not been strengthened. Whereas earthquakes became an excuse to create wealth through construction on valuable land and make those who reside in high-income neighbourhoods live, large numbers of low-income residents who live in risky buildings on low-value land are ignored and let die.\r\n\r\nThis model of disaster capitalism serves the upper and upper-middle classes, investors, and construction firms. In Istanbul, the massive urban transformation justified by safety is indeed reduced to a simple material and financial bargain. While the rich aim to get richer, the poor struggle to avoid internal exile and the loss of their right to accessible, affordable housing.\r\n\r\n<b>The Case of Kadıköy and Moda</b>\r\n\r\nKadıköy and its Moda neighbourhood are under earthquake risk; however, the level of risk in Kadıköy is significantly lower compared to neighbourhoods on Istanbul's European side or the Marmara Sea coast. Moreover, while the building stock in Kadıköy is old, it is an established and planned area where buildings are often in better condition than the squatter settlements in other districts. Although Kadıköy is not a priority area in terms of seismic risk, it ranks first in Istanbul for the speed of urban transformation and the number of buildings demolished and reconstructed. Clearly, earthquake risk in this district is utilized primarily for the creation of urban rent.\r\n\r\nIn Moda, one of the wealthiest neighbourhoods in one of the most affluent districts of Istanbul and Türkiye, urban transformation continues at a rapid pace. Kadıköy was recently ranked as the top district in the country for human development. The area is largely populated by upper-middle-class families, artists, and a considerable expat population. With its numerous restaurants, bars, live music venues, and theatres, Kadıköy attracts over a million visitors during the weekends.\r\n\r\nIn Moda, buildings near the seashore and parks, where land value is highest, have been demolished and reconstructed one by one. Land prices are among the highest in Istanbul, and residents whose buildings have not yet been transformed are often eager to find contractors to sign a deal. Contractors are equally keen to enter this market. Typically, contractors receive the rights to a third of the land of the transformed building in exchange for the cost of reconstruction. They use this portion to construct additional apartments for sale. Consequently, the apartment sizes for original property owners shrink to about two-thirds of their former size.\r\n\r\nDespite this reduction in space, owners can now market their properties as \"earthquake-resilient\" and brand new. On average, there is a 70–100% increase in house prices following the two-year demolition and rebuilding process. Such a price hike in an already overpriced neighbourhood represents an enormous accumulation of wealth in a short window. For the residents who support urban transformation, this is viewed as a \"win-win\" financial deal for both the developer and the property owner.", "time": "09:15-15:00", "provider": "Murat Güney", "provider_link": "/providers.html#provider-1071", "capacity": "10", "registered": 5, "is_full": false, "has_whatsapp": true}, "1073": {"title": "June6_Three Layers of Transformation in Kadıköy: Big Infrastructure Investments, Cultural Flagship Projects, and Neighborhood Gentrification", "description": "This excursion explores recent urban transformations in Kadıköy, one of Istanbul’s central districts on the Asian side. Over the last decade, the district has gained increasing international visibility, emerging as an important cultural and urban destination. The walk traces the transformations in Kadıköy through three interconnected sites: the Söğütlüçeşme Terminal development, Hasanpaşa–Müze Gazhane, and Yeldeğirmeni. Following a route shaped by transport infrastructure, public investment and neighbourhood change, the walk focuses on how mobility, commercial development, cultural flagship projects and municipal beautification policies interact in reshaping urban space.\r\n\r\n<b>The Flow : </b>The excursion begins at Söğütlüçeşme, one of Istanbul’s most strategic transport hubs, where the Marmaray line intersects with metrobus, regional rail and bus connections. Here, participants will explore the recently developed Söğütlüçeşme “Terminal” project, located directly beneath the Marmaray station. The complex combines retail functions with cultural facilities, inserted into a major piece of transportation infrastructure.\r\n\r\nThe project has triggered significant public debate regarding the commercialization of infrastructure spaces and the transformation of strategic public transport land into mixed-use commercial developments. It offers an opportunity to discuss broader questions surrounding mobility, privatization and the changing role of public infrastructure in contemporary urban development.\r\n\r\nFrom Söğütlüçeşme, the walk continues to Hasanpaşa–Müze Gazhane, a former industrial gasworks converted into a large-scale cultural complex and public venue. It represents a major example of heritage reuse and culture-led urban regeneration.\r\n\r\nAs a major public investment, Müze Gazhane offers an important example of adaptive reuse and inclusive cultural infrastructure. A former industrial facility has been transformed into a widely accessible public venue hosting exhibitions, concerts, libraries, workshops and everyday social activities. Rather than functioning solely as a destination-oriented cultural flagship, Gazhane has become part of residents’ daily routines, attracting diverse users across age and social groups.\r\n\r\nAt the same time, the project opens up broader questions about how inclusive cultural spaces interact with surrounding urban transformation processes and whether such projects can support accessibility and public life while coexisting with ongoing commercial pressures in the area.\r\n\r\nThe final stop is Yeldeğirmeni, a historic neighbourhood situated around one of the most important transport intersections on Istanbul’s Asian side, near Ayrılıkçeşmesi Station, where the Marmaray line connects with the metro network.\r\n\r\nSince the early 2010s—particularly after 2013—the neighbourhood has undergone rapid commercial gentrification, followed by a slower but increasingly visible residential transformation. This process has been closely linked to large-scale transport investments, nearby shopping mall developments, and municipal urban beautification policies, including mural programs, pedestrian improvements and cultural activities. Together, these interventions contributed to the rebranding of Yeldeğirmeni as a vibrant cultural and creative district.\r\n\r\nRather than presenting a fixed narrative, the excursion aims to function as a collective exploratory walk. Participants will be invited to reflect on the connections between infrastructure, culture-led regeneration and gentrification processes, and to discuss possible future trajectories for the district.\r\n\r\n<img class=\"aligncenter size-full wp-image-1074\" src=\"/assets/Ekran-Resmi-2026-05-27-11.42.34.jpg\" alt=\"\" width=\"2202\" height=\"1105\" />\r\n\r\n&nbsp;\r\n\r\n&nbsp;\r\n\r\n<strong>Technical Information</strong>\r\n\r\n&nbsp;\r\n\r\nWe will meet at 09:15 in front of Konak Hotel with one of the excursion leaders, Araf Öykü Türken. From there, we will take the metro to Yenikapı and continue by Marmaray to Söğütlüçeşme Station, where the excursion route and site discussions will begin. The tour will mainly be on foot, following an urban walking route through the selected sites. The route includes short walking distances, but also some gently sloping streets and uneven urban surfaces. Participants are advised to wear comfortable shoes. In physical terms, this is a “moderate” walking tour.\r\n\r\nThis tour is conducted by\r\n\r\nAysim Türkmen / <a href=\"mailto:aysimt@yahoo.com\">aysimt@yahoo.com /</a>+90 532 410 63 62\r\n\r\nTolga Islam / tolgaislam@gmail.com<span class=\"Apple-converted-space\">  / </span>+90 536 622 48 00\r\n\r\nAraf Öykü Türken / araf.turken@gmail.com / +90 5334329782", "time": "09.15-15:00", "provider": "Araf Öykü Türken, Aysim Türkmen, Tolga İslam", "provider_link": "/providers.html#provider-1075", "capacity": "12", "registered": 12, "is_full": true, "has_whatsapp": true}, "1077": {"title": "June5_Production Ecosystem Under Pressure: Craft Neighborhoods and Urban Transformation in Beyoğlu", "description": "<b>From Galata Tower to Perşembe Bazaar, the shores of the Golden Horn</b>\r\n\r\n&nbsp;\r\n\r\nIn Istanbul, where rapid urban transformation has reshaped the city over the last few decades, many neighborhoods have been deeply affected by these processes. This transformation impacts not only residential areas, but also production and craft districts. Istanbul’s craft neighborhoods have existed in the city center for centuries. Their continued presence allows us to discuss production not merely as an economic activity, but as a complex ecosystem shaped by social, cultural, economic, and spatial relations.<span class=\"Apple-converted-space\"> </span>\r\n\r\nDistricts such as Grand Bazaar, Şişhane, Galata, Karaköy, Eminönü, and Perşembe Bazaar contain ecosystems unique to Istanbul, shaped through the intertwined relationships between small-scale production, craftsmanship, and trade. Different stages of production are distributed among various craftspeople, workshops, shops, hans, and streets that operate through cooperation, friendship, shared knowledge, and production. Shared molds, materials, tools, and production spaces create a collective language and culture of making. Beyond economic relations, social and cultural ties between craftspeople ensure the continuity of these ecosystems. As UNESCO states, safeguarding traditional craftsmanship should focus not only on preserving craft objects, but on sustaining the skills, knowledge, and transmission of craftsmanship within communities.\r\n\r\nFor many years, these craft-based and micro-scale production areas located in the city center have been under threat from mainstream urban policies and planning decisions aiming to remove production from central and historical urban areas. In addition to these top-down pressures, rapid gentrification, tourism-oriented transformation, rising rents, and property speculation increasingly displace already fragile production actors from both their workplaces and neighborhoods.\r\n\r\nFollowing the Historic Peninsula and Beyoglu Conservation Master Plans, production areas in Istanbul’s historic centre, including Şişhane and Galata, were redesignated as “Trade-Service-Tourism (TST)” zones. These planning policies framed manufacturing as a threat to the historic urban fabric and promoted the relocation of long-established production activities away from the city centre. In doing so, they largely disregarded the area’s century-old production ecosystem, its communities, local economy, and cultural identity. In 2010, Perşembe Pazarı was also declared an “Urban Renewal Area” under Law No. 5366. The renewal decisions aimed to remove activities such as hardware trade, small-scale manufacturing, and maritime-related craftsmanship, despite these practices forming the historic identity of the district for centuries.\r\n\r\nToday, there is an urgent need for new arguments, alternative visions, and sustainable approaches to safeguard Istanbul’s craft neighborhoods against top-down transformation processes. At a time when both urban policies and design practices are rapidly adapting to new global economic orders, it becomes increasingly important to understand and redefine the intimate relationship between micro-scale production, culture, economy, labour, and urban life.\r\n\r\n<b>The Route of the Excursion</b>\r\n\r\nTour will start on Elmadag Bus Stop at 08:30. It will continue  from Şişhane Square. It stretching from <b>Galata </b>and <b>Şişhane</b> Districts down toward <b>Perşembe Bazaar</b>, focuses on forms of production suspended between the traditional and the modern — carrying characteristics of both, yet fully belonging to neither. Throughout the walk, this production ecosystem will be discussed through — and beyond — the frameworks of labour, craftsmanship, education, cultural heritage, sustainability, design, and urban struggle. Together with participants, we will collectively witness, observe, and reflect on these realities on site.\r\n\r\nThe guide of the walk has maintained a deep and long-standing relationship with the area since the late 1990s. Beginning as a designer working with a lighting manufacturer in Şişhane, she later initiated the <b>Made in Şişhane</b> project and has dedicated more than twenty years to the sustainability and visibility of the district’s production-craft culture. For over a decade, she has also developed strategic collaborations connecting formal education actors with craft neighborhoods, opening discussions around alternative forms of urban resistance, critical design practices, and urgent pedagogies.\r\n\r\nThe walk will unfold through these rooted relationships and long-term encounters with the area. Participants will visit craftspeople and workshops that are both socially, economically, and historically embedded within the district: an Armenian master for metalworks and his 60-year-old craft practices; a percussion instrument maker and local brand; a wood carving atelier inherited from father to son; one of the few remaining neon workshops once part of the district’s sign-making cluster, now run by two brothers continuing their father’s practice; vertically organized production hans in Şişhane; streets specialized in particular production and commerce activities; a metal spinning workshop preserving an inherited archive of molds and tools; the last remaining steel spring workshop in Kurşunlu Han, which is currently experiencing step-by-step gentrification; and Perşembe Pazarı itself, an area that has long been subjected to renewal and transformation pressures.\r\n\r\nThroughout this journey, participants will closely encounter different actors, spatial forms, and production cultures within Istanbul’s craft ecosystem, while also witnessing the physical manifestations of urban transformation and gentrification. Along the route, we will also meet designers, artists, and cultural practitioners who live and work in the area and who continue to engage with these ongoing urban processes.\r\n\r\n<img class=\"aligncenter size-full wp-image-1078\" src=\"/assets/Anil-Cizmecioglu-kumbaraci_ahsap_8.jpeg\" alt=\"\" width=\"1280\" height=\"853\" /> <img class=\"aligncenter size-full wp-image-1079\" src=\"/assets/Galata-Fotografhanesi-Fotograf-Akademisi-IMG_1565h.jpg\" alt=\"\" width=\"1280\" height=\"853\" /> <img class=\"aligncenter size-full wp-image-1080\" src=\"/assets/MIS_arifyaman003.jpg\" alt=\"\" width=\"1280\" height=\"852\" /> <img class=\"aligncenter size-large wp-image-1081\" src=\"/assets/MIS_arifyaman012-1024x682.jpeg\" alt=\"\" width=\"1024\" height=\"682\" />\r\n\r\n<b>Physical features</b><b></b>\r\n\r\nAfter a short public transfer, we will need to walk quite a bit. The distances are not long, but the terrain is uneven and we will often be going up and down the hills.\r\n\r\nWe will have lunch at a local restaurant in Galata\r\n\r\n<b>Departure: 08:30 Elmadağ Bus Stop</b>\r\n\r\n<b>The tour will be conducted by Aslı Kıyak Ingin</b>\r\n\r\n<b>email:aslikiyak@gmail.com</b>\r\n\r\n<b>whatsapp: +90 542 3476241</b><b></b>", "time": "08:30-15:00", "provider": "Aslı Kıyak İngin", "provider_link": "/providers.html#provider-940", "capacity": "10", "registered": 10, "is_full": true, "has_whatsapp": true}, "1082": {"title": "June6_Urban Food Communities as a Form of Solidarity, Struggle, Commons and Care", "description": "This excursion focuses on collective practices and initiatives that view food not merely as consumption but as a way of commons, solidarity, ecological justice, and urban struggle.\r\n\r\nHow can alternative food networks be shaped in the city? Can farmers’ markets, urban gardens (“bostans”), cooperatives, and community initiatives function as a form of resistance against mainstream urban practices? And can these help to build a sustainable, community- and nature-based, resilient, and self-sufficient city? Throughout the walk, we will explore different forms of collective food practices and movements.\r\n\r\n<b>Our Stations and Encounters</b><b></b>\r\n\r\nOur first stop,<b> Feriköy Ecologic Food Market,</b> has aimed to establish a direct, trust-based model that seeks to become an alternative to industrial food chains by bringing certified small-scale farmers together with consumers since 2006. The market was established in partnership with the Buğday (“Wheat”) Association and Şişli Municipality.\r\n\r\n<b>Buğday Association</b> has been working on ecological living, clean food, agroecology, and sustainable production-consumption relations. Through projects such as ecologic markets, the TaTuTa ecological farm network, seed-sharing initiatives, and community-supported agriculture, the association has contributed to the expansion of alternative food systems and ecological awareness since the 1990s.\r\n\r\n<b>Piyalepaşa Urban Garden</b> is a 400-year-old historic bostan and a listed site. The historical Piyalepaşa and Yedikule Urban Gardens, where farming and cultivation are still carried out by bostancı families, have faced the threat of destruction over the last two decades. The Piyalepaşa Bostan Defence is a local solidarity movement that emerged to protect this bostan. This struggle views the bostans not merely as areas of agricultural production, but as part of collective memory, cultural heritage, labour, neighbourhood relations, and the right to the city.\r\n\r\n<b>Beyoğlu Food Community</b> is a solidarity-based initiative that aims to build a fair, ecological, and sustainable food system between local producers and consumers. Ensuring access to fair and ecological food; supporting small-scale producers and fostering networks of solidarity; building trust-based relationships between producers and consumers; promoting sustainability and local production; and creating a transparent and community-driven model are among the principles of this initiative.\r\n\r\n<b>Campus Gardens Initiative</b><b></b>\r\n\r\nUniversity campus gardens in Istanbul are emerging as food communities that bring together learning, production, and living. These campus gardens function as common ground for labour, solidarity, and sharing, where students and academics come together. The Campus Gardens Initiative was established to encourage collaboration, knowledge exchange, and solidarity among university gardens across the city.\r\n\r\n<b>Kuzguncuk Community Garden</b><b></b>\r\n\r\nPreserved through long-term neighborhood resistance, this urban garden has survived and become an important example of defending urban commons in the city. Against ongoing urban transformation pressures, it continues to exist as a living public space that embodies collective memory, ecological awareness, and neighbourhood solidarity.\r\n\r\n<b>The Time Table</b>\r\n\r\n9:00 Departure from Elmadağ Busstop - Northbound (opposite side of the Konak hotel)\r\n\r\n9:15 -10:10 Feriköy Ecologic Food Market and Buğday Association\r\n\r\n10:30 -11:30 Piyale Paşa Urban Farm, Bostan\r\n\r\n11:50 -12:30 Beyoğlu Food Community (with Campus Gardens Initiative)\r\n\r\n12:45 departure from Kabataş piers to the Asian side\r\n\r\n13:45 Kuzguncuk Community Garden, Bostan\r\n\r\n15:30 TAK\r\n\r\n<img class=\"aligncenter size-large wp-image-1083\" src=\"/assets/Ekran-Resmi-2026-05-28-00.34.29-1024x768.jpg\" alt=\"\" width=\"1024\" height=\"768\" /> <img class=\"aligncenter size-large wp-image-1084\" src=\"/assets/Ekran-Resmi-2026-05-28-00.34.12-1024x771.jpg\" alt=\"\" width=\"1024\" height=\"771\" /> <img class=\"aligncenter size-large wp-image-1085\" src=\"/assets/Ekran-Resmi-2026-05-28-00.33.50-1024x764.jpg\" alt=\"\" width=\"1024\" height=\"764\" />\r\n\r\n<b>Physical features:</b>\r\n\r\nWe will be using a chartered minibus to get to the various locations in European side. We will cross from the European side to the Asian side by public ferry boat. We will use public transport and walk a little bit in Asian Side. We will visit bostans (urban gardens) don’t forget to take your sun protection, water and hat with you. Walking distance in European Side is very limited. Due to the distance between stations to be visited, this excursion will be a bit longer than the other excursions, We will finish later.<b>\r\n</b>\r\n\r\n<b>Suggested Lunch</b>: <span class=\"Apple-converted-space\"> </span>\r\n\r\nWe will take the lunch at TAK Kadıköy (the conference venue) as organised for the entire group. As a part of the excursion on food ecosystem, you can buy snacks as a gesture of solidarity with the communities and enjoy delicious, fair-trade and healthy food during your ferry journey. We will be discussing and debating the food system by engaging all our senses\r\n\r\n<b>Departure from Konak Hotel/Elmadag Bus Stop at 9:00 AM.</b>\r\n\r\n<b>The tour will be conducted By Aslı Kıyak Ingin</b>\r\n\r\n<b>email: aslikiyak@gmail.com</b>\r\n\r\n<b>whatsapp:+90 542 3476241</b>", "time": "09:00-15:30", "provider": "Aslı Kıyak İngin", "provider_link": "/providers.html#provider-940", "capacity": "10", "registered": 6, "is_full": false, "has_whatsapp": true}, "1091": {"title": "June5_Sarıyer–Derbent: Negotiating Urban Transformation at Istanbul’s Metropolitan Frontier", "description": "This excursion explores Derbent, an informal settlement (gecekondu) in Istanbul's Sarıyer district, where residents have fought for decades to secure legal rights to their homes and land. As the area gained value due to its proximity to Istanbul's business district, the state and private developers increasingly pressured residents to leave or accept unfavorable redevelopment terms.\r\n\r\nRather than accept displacement, residents organized themselves, forming cooperatives and associations, filing lawsuits, and engaging with local officials. Through persistence and collective action, they gradually shifted how the neighborhood was governed, gaining recognition of their rights and participation in urban decision-making processes.\r\n\r\nThe excursion examines how ordinary residents navigated state policies, private development interests, and bureaucratic processes to protect their community. It highlights the micropolitics of urban life: how people organize, negotiate with authorities, assert their presence, and shape the future of their neighborhoods in the face of powerful pressures to change.\r\n\r\nMain themes along the route will be\r\n<ul>\r\n \t<li>informal settlement dynamics<span class=\"Apple-converted-space\"> </span></li>\r\n \t<li>urban regeneration pressures<span class=\"Apple-converted-space\"> </span></li>\r\n \t<li>infrastructural expansion and metropolitan restructuring<span class=\"Apple-converted-space\"> </span></li>\r\n \t<li>ecological/forest edge urbanisation<span class=\"Apple-converted-space\"> </span></li>\r\n \t<li>community adaptation and negotiation practices</li>\r\n</ul>\r\n<a href=\"https://www.haberler.com/sariyer-in-derbent-mahallesi-icin-hazirlanan-imar-11784441-haberi/\"><img class=\"aligncenter size-large wp-image-1093\" src=\"/assets/Ekran-Resmi-2026-05-28-00.42.09-1024x287.jpg\" alt=\"\" width=\"1024\" height=\"287\" /></a>\r\n\r\n<i>Aerial view of Derbent on the hillside (Sarıyer, Istanbul)</i><i></i>\r\n\r\n<i>Source</i>: <a href=\"https://www.haberler.com/sariyer-in-derbent-mahallesi-icin-hazirlanan-imar-11784441-haberi/\">https://www.haberler.com/sariyer-in-derbent-mahallesi-icin-hazirlanan-imar-11784441-haberi/</a>\r\n\r\n<a href=\"https://www.sariyerposta.com/derbentin-imar-plani-onaylandi\"><img class=\"aligncenter size-large wp-image-1092\" src=\"/assets/Ekran-Resmi-2026-05-28-00.42.24-1024x614.jpg\" alt=\"\" width=\"1024\" height=\"614\" /></a>\r\n\r\n<i>Street-level documentation of Derbent<span class=\"Apple-converted-space\"> </span></i>\r\n\r\n<i>Source: </i><a href=\"https://www.sariyerposta.com/derbentin-imar-plani-onaylandi\"><i>https://www.sariyerposta.com/derbentin-imar-plani-onaylandi</i></a><i><span class=\"Apple-converted-space\"> </span></i>\r\n\r\n<b>Information on the route</b>\r\n\r\nThe group will travel from Konak Hotel/Elmadağ to Derbent by metro. The journey is expected to take around 45–60 minutes depending on timing and group coordination.\r\n\r\nThe excursion itself will mainly take place on foot within the neighborhood. Participants should expect approximately 1.5–2 hours of walking with several stops for discussion and observation. Estimated total walking distance within Derbent will be approximately 3–4 km.\r\n\r\nMost of the excursion will take place outdoors. No institutional office visit is planned at this stage, though short community-based encounters may occur informally during the walk.\r\n\r\nThe terrain is moderately hilly, including asphalt roads, stairways, and uneven neighborhood streets. The excursion requires moderate physical effort but does not involve difficult hiking conditions.\r\n\r\nLunch will take place at a local neighbourhood lokanta/café in the Sarıyer area (tbc depending on final route and group size).\r\n\r\n<b><span class=\"Apple-converted-space\"> </span></b><b>departure time: </b><i> 09:45 from Konak hotel</i>\r\n\r\n<i>(Adjustable if necessary for coordination purposes.)</i>\r\n\r\n<b>The tour will be conducted by Ebru Kurt-Ozman </b><b>together with Ayşe Gümec Karamuk </b>\r\n\r\n<b>Contact:  </b>ebruu.kurt@gmail.com / mobile/whatsapp: +90 537 592 47 06", "time": "09:45-15:00", "provider": "Ayşe Gümec Karamuk, Ebru Kurt Özman", "provider_link": "/providers.html#provider-1090", "capacity": "12", "registered": 12, "is_full": true, "has_whatsapp": true}, "1097": {"title": "June6_The Invisible Side of Gentrification in Istanbul’s Trendy Asian-Side Neighborhoods", "description": "<div>\r\n\r\n<span lang=\"EN-US\">This excursion explores the hidden face of gentrification in down town  Asian-side. We will be moving from Moda to Yeldeğirmeni, increasingly popular neighbourhoods of Kadıköy  district, which developed in 19th century as an important residential and commercial center. Different social geographies are layered around Kadköy’s market, its ferry connections and coastal neighborhoods: Moda became associated with more affluent and cosmopolitan residential life, while Yeldeğirmeni, closer to Haydarpaşa train station and transport infrastructures, carried histories of modest housing, migration, non-Muslim communities, labor, and early apartment life. After periods of decline, disinvestment, and physical wear in the late twentieth century, both neighborhoods have been revalued since the 2000s and 2010s, but in different ways: through cafés, cultural venues, restored buildings, short-term rentals, creative-class settlement, and new forms of consumption. This walk asks what remains behind this attractive public image: whose memories are preserved, whose lives are displaced or made invisible, and how urban belonging is reshaped through gentrification.</span>\r\n\r\n</div>\r\n<div>\r\n\r\n<span lang=\"EN-US\"> </span>\r\n\r\n</div>\r\n<div>\r\n\r\n<span lang=\"EN-US\">First part of the tour will be spent in Moda, the affluent part of Kadıköy. <span class=\"None\"><b>Moda 63 is</b></span> a memory space run by Aziz Nesin Foundation located in a former family apartment, where domestic objects, family archives, and everyday traces open a more intimate layer of Kadıköy’s urban history. The second part will take place in the modest neighbourhood of Yeldeğirmeni. Participants will walk through a short route featuring selected historic apartment buildings, which may include Altınöz Apartment, Tevfik Tura / former Demirciyan Apartment, Valpreda / Italian Apartment, and Celal Muhtar Apartment, using these buildings as street-level entry points into early apartment culture, minority and Levantine histories, Haydarpaşa-related labor and mobility, property relations, naming practices, and the transformation of the old residential fabric into today’s desirable urban landscape. The excursion will end at <span class=\"None\"><b>arthereistanbul</b></span>, an artist-run space in Yeldeğirmeni founded by displaced Syrian artists, with a short briefing on art, refuge, cultural solidarity, and the role of creative spaces in a changing neighborhood.</span>\r\n\r\n&nbsp;\r\n\r\n</div>\r\n<img class=\" wp-image-1101 alignleft\" src=\"/assets/velprada-150x150.png\" alt=\"\" width=\"253\" height=\"253\" /><img class=\"wp-image-1100 alignnone\" src=\"/assets/tevfik.png\" alt=\"\" width=\"203\" height=\"254\" />\r\n\r\n<img class=\"wp-image-1099 alignnone\" src=\"/assets/aziz_nesin.png\" alt=\"\" width=\"302\" height=\"226\" /> <img class=\"wp-image-1098 alignleft\" src=\"/assets/arthere.png\" alt=\"\" width=\"552\" height=\"221\" />\r\n<div>\r\n\r\n<span class=\"None\"><b><span lang=\"EN-US\">Physical and technical details</span></b></span>\r\n\r\n</div>\r\n<div>\r\n\r\n<span class=\"None\"><b><span lang=\"EN-US\">How to get there</span></b></span><span lang=\"EN-US\">\r\nThe participants will join other groups going to the Asian side, at the Konak Hotel / Elmadağ at 09 15. Groups will cross to the Asian side together via metro and metrobus on the highway. The tour leader meets the group at Terminal Kadıköy.</span>\r\n\r\n</div>\r\n<div>\r\n\r\n<span class=\"None\"><b><span lang=\"EN-US\">Timetable</span></b></span>\r\n\r\n</div>\r\n<div>\r\n\r\n<span class=\"None\"><b><span lang=\"EN-US\">09:15</span></b></span><span lang=\"EN-US\"> Departure Konak hotel</span>\r\n\r\n</div>\r\n<div>\r\n\r\n<span class=\"None\"><b><span lang=\"EN-US\">09:30</span></b></span><span lang=\"EN-US\"> Departure Taksim, transfer to Asia via Mecidiyeköy</span>\r\n\r\n</div>\r\n<div>\r\n\r\n<span class=\"None\"><b><span lang=\"EN-US\">10:15</span></b></span><span lang=\"EN-US\"> Arrival Terminal Kadıköy, common exploration of the Terminal, the new commercial transport hub together with other groups  </span>\r\n\r\n</div>\r\n<div>\r\n\r\n<span class=\"None\"><b><span lang=\"EN-US\">10:45</span></b></span><span lang=\"EN-US\"> Departure for Moda  </span>\r\n\r\n</div>\r\n<div>\r\n\r\n<span class=\"None\"><b><span lang=\"EN-US\">11:15</span></b></span><span lang=\"EN-US\"> Moda 63</span>\r\n\r\n</div>\r\n<div>\r\n\r\n<span class=\"None\"><b><span lang=\"EN-US\">12:30</span></b></span><span lang=\"EN-US\"> Departure for Yeldeğirmeni through the historic Kadıköy Çarşı (Bazaar), street level stroll with apartments</span>\r\n\r\n</div>\r\n<div>\r\n\r\n<span class=\"None\"><b><span lang=\"EN-US\">13:30</span></b></span><span lang=\"EN-US\"> Arthere</span>\r\n\r\n</div>\r\n<div>\r\n\r\n<span class=\"None\"><b><span lang=\"EN-US\">14:30</span></b></span><span lang=\"EN-US\"> Arrival TAK, common lunch</span>\r\n\r\n</div>\r\n<div>\r\n\r\n<span class=\"None\"><b><span lang=\"EN-US\">The walk, the terrain and the difficulty level</span></b></span>\r\n\r\n</div>\r\n<div>\r\n\r\n<span lang=\"EN-US\">The total walking distance is approximately 4 - 4,5 km, within ca 2 hrs, depending on the final number of apartments stops in Yeldeğirmeni. The walking itself will take around 75–90 minutes. Approximately 1–1.5 hours will be spent indoors, mainly at Moda 63 and during the final briefing at arthereistanbul. The apartment buildings in Yeldeğirmeni will be observed from the outside as short street-level stops.</span>\r\n\r\n</div>\r\n<div>\r\n\r\n<span lang=\"EN-US\">\r\nThe route is mostly urban asphalt and pavement. Some sidewalks may be narrow, uneven, or crowded. There may be mild slopes and some cobbled or uneven surfaces, especially in side streets. The tour is <span class=\"None\"><b>physically Easy to medium.</b></span> The route does not require intense physical effort, but participants should be comfortable walking for several hours with pauses. Comfortable walking shoes are recommended.</span>\r\n\r\n</div>\r\n<div>\r\n\r\n<span lang=\"EN-US\">As lunch will be taken late snacks and tea/coffee will be organized during the field trip.</span>\r\n\r\n</div>\r\n<div>\r\n<p class=\"BodyA\"><span class=\"None\"><b><span lang=\"EN-US\">The tour will be conducted by Ezgi Karaoğlu</span></b></span></p>\r\n\r\n<div>\r\n<div>\r\n<p class=\"BodyA\"><span class=\"None\"><b><span lang=\"EN-US\">Email:</span></b></span><span class=\"None\"><span lang=\"EN-US\">\r\n</span></span><span class=\"None\"><span lang=\"EN-US\">ezgikaraoglu@gmail.com</span></span></p>\r\n\r\n</div>\r\n<div>\r\n<p class=\"BodyA\"><span class=\"None\"><b><span lang=\"EN-US\">WhatsApp &amp; Signal number:</span></b></span><span class=\"None\"><span lang=\"EN-US\">\r\n</span></span><span class=\"None\"><span lang=\"EN-US\">+905431719477</span></span><b></b></p>\r\n\r\n</div>\r\n<div>\r\n<p class=\"BodyA\"><span class=\"None\"><b><span lang=\"DE\">arthereistanbul</span></b></span><span class=\"None\"><span lang=\"EN-US\">\r\n</span></span><span class=\"None\"><span lang=\"DE\">Website: arthereistanbul.com</span></span></p>\r\n\r\n</div>\r\n<div>\r\n<p class=\"BodyA\"><span class=\"None\"><b><span lang=\"EN-US\">Moda 63</span></b></span><span class=\"None\"><span lang=\"EN-US\">\r\n</span></span><span class=\"None\"><span lang=\"EN-US\">Instagram account: @nesinmoda63.</span></span></p>\r\n\r\n</div>\r\n</div>\r\n</div>", "time": "09:15-15:00", "provider": "Ezgi Karaoğlu", "provider_link": "/providers.html#provider-947", "capacity": "10", "registered": 10, "is_full": true, "has_whatsapp": true}, "1133": {"title": "June6_Fikirtepe, the second most dense residential area on the planet. Neoliberal win-win model hitting the wall", "description": "During the last decade, the visuals of that “lonely house” (see below) became viral, but Fikirtepe did not need such an icon to occupy a central role in the public narrative of Istanbul’s urban transformation. After much-criticized early urban transformation disasters such as Sulukule, Tarlabaşı, and others — subjects of investigation in the first INURA activities in Istanbul — the now-mature AKP government identified Fikirtepe as the site of its “success story” in urbanism.\r\n\r\nAll preconditions looked perfect for a neoliberal fairy tale: the densely built-up post-gecekondu area had a politically conservative profile, and as supporters of the government, its residents were expected to be rewarded with one of the “wins.” Its location — very close to the lively downtown of Kadıköy and directly between two major highway intersections — made it highly attractive to the development and real estate industries, which were used to taking that other win anyway, regardless of whether another winner was foreseen or not. The government generously created the preconditions and then drew back. The grant of a Floor Area Ratio of net 4.0 / brutto up to 6.0 would let the market take care of the rest and transfer the rural-origin population into upscale condos, cementing their final arrival at the center of urban society. The conservative community would willingly cooperate. Unlike in many other transformation areas, there was indeed no collectively organized contestation, but only partially fierce individual bargaining.\r\n\r\nAfter two decades that read like a criminal novella, the outcome is now visible: future residents are moving in, pavements are being finished, and hyperactive real estate marketing is flooding social media. Fikirtepe — the site of an 8,500-year-old Neolithic harbor settlement; a semi-rural area in the late 19th century, famous for its mansions and farms growing okra and strawberries; and, from the 1950s onward, one of the earliest working-class gecekondu areas on the old Ankara highway — is expected soon to reach a population density of 1,076 residents per hectare. Worldwide, this is second only to the infamous Mong Kok in Hong Kong (1,300 residents per hectare).\r\n\r\nThe 130-hectare area was declared a special project area in 2005, an urban transformation area in 2007, and a high-risk area in 2014. Due to fierce individual bargaining, rapid expropriation regulations were enforced in 2015. When private developers on 40% of the total area went bankrupt and failed to finish their works, then simply evaporated around 2020, with the banks carving their debts into the land deeds, the Ministry of Environment, Urbanization and Climate Change had to take over the projects in order to prevent a scandal on a massive scale and limit the damage to political reputation. The taxpayer and the former post-gecekondu owners have paid — and are still being asked to pay — the costs. Organized community efforts emerged only afterwards to sue the ministry and the developers.\r\n\r\nFikirtepe is a place of superlatives in both process and outcome. No other recent development has been more fiercely criticized by the scholarly community for its dystopian qualities. The standards of the 25–30 story settlement, which soon 140 000 people will call home and 60 000 their workplace, are simply catastrophic in terms of climate-change compatibility, green space, mobility, public amenities, and disaster preparedness. On the other hand, Fikirtepe is the first high-rise mass-housing area that is not explicitly gated, reflecting an attempt to create a walkable, Manhattan-like public space at ground level. Too weak a consolation?\r\n\r\nDuring the Retreat, <b>Ebru Kurt Özcan</b> will give a presentation focusing on the \"citizen entrepreneurialism\" aspect of the Fikirtepe redevelopment, which forms part of her PhD research. This field trip is offered as a preparatory exploration prior to her talk in Nicea/İznik.\r\n\r\n<b>The Flow</b>\r\n<ul>\r\n \t<li><b>09:15</b> — <b>Departure from Elmadağ/Konak Hotel</b>: We will take the subway to the highway ring at Mecidiyeköy, and transfer to the Metrobus to cross over to the Asian side. Total travel time is approximately 35–40 minutes.</li>\r\n \t<li><b>10:15 —</b> <b>The \"Terminal\" Hub</b>: Before starting our walking tour in Fikirtepe, we will spend some time at the \"Terminal\"—the new transportation hub for Kadıköy featuring commercial infrastructure and public facilities.</li>\r\n \t<li><b>11:00</b> — <b>Fikirtepe Exploration</b>: In the densely packed Fikirtepe area, we will explore various public and communal spaces, sales offices and possibly access some interiors. Encounters with local actors will be a mix of planned meetings and spontaneous interactions.</li>\r\n \t<li><b>13 15 </b>— <b>Transfer to Kadıköy and walk to Yeldeğirmeni</b>: After Fikirtepe, we will proceed by subway to downtown Kadıköy. In the neighborhood of Yeldeğirmeni, we will visit the site of a demolished apartment building currently subject to urban transformation negotiations. This spot holds personal history: It was once the family home of the tour leader’s grandparents at the waterfront - before the 1970s coastal landfill. The house was redeveloped by his grandmother into an apartment building in the late 1970s and pulled down in 2025. A company which inhabited 2 floors of the demolished building has temporarily resettled to Fikirtepe. (Visit of their office in Fikirtepe requested)</li>\r\n \t<li><b>14:00</b> — <b>Lunch at TAK</b>: The site is only steps away from TAK (Tasarım Atölyesi Kadıköy), where we will meet up with the other groups for lunch and later for the workshops to evaluate the fieldtrips.</li>\r\n</ul>\r\n<img class=\"aligncenter size-full wp-image-1135\" src=\"/assets/Resim1.jpg\" alt=\"\" width=\"929\" height=\"572\" />\r\n<div>\r\n<p class=\"Body\">The <span lang=\"IT\">iconic</span> “lonely house of Fikirtepe” source: <span class=\"Hyperlink0\"><a href=\"https://bianet.org/yazi/fikirtepe-den-inattepe-ye-manhattan-macerasi-158476\">https://bianet.org/yazi/fikirtepe-den-inattepe-ye-manhattan-macerasi-158476</a></span></p>\r\n<img class=\"aligncenter size-full wp-image-1136\" src=\"/assets/Resim2.jpg\" alt=\"\" width=\"1004\" height=\"431\" />\r\n\r\n</div>\r\n<div>\r\n<p class=\"Body\"><i>the post-gecekondu before demolishing</i></p>\r\n\r\n</div>\r\n<div>\r\n<p class=\"Body\"><i>source: </i><span class=\"Hyperlink0\"><a href=\"https://www.fikirtepemedya.com/siyaset/fikirtepe-ve-kadikoye-dair-bir-kisisel-tarih/\"><i>https://www.fikirtepemedya.com/siyaset/fikirtepe-ve-kadikoye-dair-bir-kisisel-tarih/</i></a></span><i></i></p>\r\n<img class=\"aligncenter size-full wp-image-1137\" src=\"/assets/Resim3.jpg\" alt=\"\" width=\"1004\" height=\"668\" /> <img class=\"aligncenter size-full wp-image-1138\" src=\"/assets/Resim4.jpg\" alt=\"\" width=\"1004\" height=\"554\" />\r\n\r\n</div>\r\n<div>\r\n<p class=\"Body\"><i>source:</i><span class=\"Hyperlink0\"><a href=\"https://onedio.com/haber/15-yildir-donusturulemeyen-kentsel-donusum-fikirtepe-devlete-yuk-olmaya-devam-ediyor-1064813\"><i>https://onedio.com/haber/15-yildir-donusturulemeyen-kentsel-donusum-fikirtepe-devlete-yuk-olmaya-devam-ediyor-1064813</i></a></span><i></i></p>\r\n\r\n</div>\r\n<b><span class=\"Apple-converted-space\"><img class=\"aligncenter size-full wp-image-1139\" src=\"/assets/Resim5.jpg\" alt=\"\" width=\"843\" height=\"631\" /><img class=\"aligncenter size-full wp-image-1140\" src=\"/assets/Resim6.jpg\" alt=\"\" width=\"754\" height=\"1004\" /></span></b>\r\n<div>\r\n<p class=\"Body\"><i>Fikirtepe, May 2026, photos: Orhan Esen</i></p>\r\n\r\n</div>\r\n<b><span class=\"Apple-converted-space\"> </span></b>\r\n\r\n<b>Physical Conditions &amp; Info</b>\r\n<ul>\r\n \t<li><b>Terrain &amp; Elevation</b>: <i>Tepe</i> means \"The Hill\" in Turkish. Fikirtepe is a hilltop plateau situated roughly 30 meters above the Metrobus station (starting point) and 50 meters above the subway station entrance.(finishing point)</li>\r\n \t<li><b>Walking Distance</b>: We will walk no more than 3 kms within 2 hours in Fikirtepe. In the Kadıköy/Yeldeğirmeni section, we will walk an additional 1.5 km, with the final stretch being a gentle uphill slope.</li>\r\n \t<li><b>Difficulty Level</b>: Altogether, this is a <b>moderately difficult</b> excursion.</li>\r\n \t<li><b>Snacks and Coffee:</b> Can be easily purchased at various corners during the stroll. Invitations by Real Estate agents may be expected, too.</li>\r\n \t<li><b>Group Limit</b>: <b>9 participants</b>.</li>\r\n</ul>\r\n&nbsp;\r\n<ul>\r\n \t<li><b>The field trip will be conducted by Orhan Esen.</b></li>\r\n \t<li><b>Email</b>: <a href=\"mailto:orhan@urbanitiez.com\">orhan@urbanitiez.com</a> <a href=\"mailto:coordination@inura26istanbul.net\">coordination@inura26istanbul.net</a></li>\r\n \t<li><b>WhatsApp</b>: +49 152 3842 5003</li>\r\n \t<li><b>Signal</b>: +90 535 57 00 325</li>\r\n</ul>", "time": "09:15-15:00", "provider": "Orhan Esen", "provider_link": "/providers.html#provider-944", "capacity": "9", "registered": 9, "is_full": true, "has_whatsapp": true}}};
